import{H as e,at as t,it as n,vt as r}from"./chunks/framework.dmHZ7NHG.js";var i=JSON.parse(`{"title":"@uuidna/research Documentation","description":"","frontmatter":{},"headers":[],"relativePath":"packages/research/docs/README.md","filePath":"packages/research/docs/README.md"}`),a={name:`packages/research/docs/README.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="uuidna-research-documentation" tabindex="-1">@uuidna/research Documentation <a class="header-anchor" href="#uuidna-research-documentation" aria-label="Permalink to “@uuidna/research Documentation”">​</a></h1><p>Deep research framework: recomputable research through the imprint codec, corroboration scans, book/movie/record/standard audits, publication composition, the reporter&#39;s method, prior art anchoring, and forward-chaining reasoning.</p><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to “Modules”">​</a></h2><ul><li><strong>Deep Research</strong> (<code>deepResearch</code>) — execute multi-dimensional research audits with corroboration requirements</li><li><strong>Publication Pipeline</strong> (<code>composePublication</code>, <code>auditPublication</code>, <code>revisePublication</code>) — seal research findings as publications with theorem citations and gating</li><li><strong>Content Audits</strong> (<code>auditBook</code>, <code>auditMovie</code>, <code>auditStandard</code>, <code>auditCve</code>) — prove provenance and integrity of published works</li><li><strong>Research Evidence</strong> (<code>corroborate</code>, <code>researchEvidence</code>) — cross-reference findings with ≥2 independent sources</li><li><strong>Theorem Linking</strong> (<code>extractDecidable</code>, <code>linkBookFacts</code>) — bind discovered facts to the sealed ledger</li><li><strong>Vocabulary &amp; Terms</strong> (<code>vocabulary</code>, <code>nistConstant</code>) — canonical terminology and NIST constant anchors</li><li><strong>Reasoning</strong> (<code>reason</code>, <code>reflects</code>, <code>priorArt</code>) — forward-chaining derivations and reflection</li></ul><h2 id="core-documents" tabindex="-1">Core Documents <a class="header-anchor" href="#core-documents" aria-label="Permalink to “Core Documents”">​</a></h2><ul><li><strong><a href="./training">Training Guide</a></strong> — deep research workflow, captain claims, honest scope, content addressing, MCP integration</li></ul><h2 id="honest-scope" tabindex="-1">Honest Scope <a class="header-anchor" href="#honest-scope" aria-label="Permalink to “Honest Scope”">​</a></h2><p>Research here extracts <strong>PROVENANCE and STRUCTURE, never meaning</strong>. A publication publishes only when:</p><ul><li>Honesty gate clears (theorem citations verify)</li><li>Corroboration holds (≥2 independent sources)</li><li>Content addresses are recomputable (order-invariant folds)</li></ul><p>Integrity is provable. Truth is not. Research here proves what was published and who published it, never whether it is true in the world.</p><hr><p>Licence: CC BY-NC-ND 4.0 · © Tsvetan Rouschev.</p>`,12)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};